/**
 * 负责奇迹商人从实际库存选择赠予。输入为当前原体与验证后的技能／收货选择，输出为赠予、反噬及交易事实。
 * 阵营只在原点晚查实际值，同值组件替换不增加引用撤权；新请求、关窗或首付款之前拒绝已退休源。
 * 原 ownerCurrent 仍复验已付反噬的生命与身份，目标／知识不按运行墓碑裁剪。Good 授予正常返回后，
 * 商人库存、成交记录和事实仍按原完成前缀继续；Wolf 在商人库存首写付款，异常不退款或回滚。
 */
import { closeMerchantTrade, recordMerchantTrade } from "./state";

import type { MiracleSkill } from "@ai-werewolf-arena/game-contract";

import { COMPONENT } from "../../../../core/domain/components/names";
import { isRoleExecutionRetired } from "../../../../core/domain/role-execution-authority";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { Camp, Role, Phase, WitchSelfHealRule, type ToolCall } from "../../../../core/domain/model";
import { captureNightLife, livingNightLife } from "../../../../core/domain/night_effects";
import type { World } from "../../../../core/domain/world";
import type { NightStageHandler } from "../../stages/night/contracts";
import { grantNightAbility } from "../night-ability-grants";
import { canMerchantTrade, getMerchantState } from "./state";

const committed = new WeakMap<World, Set<number>>();
export function hasMerchantNightCommit(world: World, day: number): boolean {
  return committed.get(world)?.has(day) ?? false;
}
function recordCommit(world: World, day: number): void {
  const days = committed.get(world) ?? new Set<number>();
  days.add(day);
  committed.set(world, days);
}

export const MIRACLE_MERCHANT_STAGE: NightStageHandler = {
  id: "miracle_merchant",
  priority: 125,
  async execute(ctx) {
    const day = ctx.currentDay();
    for (const actorId of ctx.getAliveByRole(Role.MiracleMerchant)) {
      const role = ctx.world.getComponent(actorId, COMPONENT.Role)!,
        state = getMerchantState(role),
        life = captureNightLife(ctx.world, actorId);
      if (!state || !life || ctx.world.getComponent(actorId, COMPONENT.Camp)?.camp !== Camp.Good) continue;
      const privateState = role.privateState;
      const ownerCurrent = () =>
        ctx.isCurrent() &&
        ctx.world.getComponent(actorId, COMPONENT.Role) === role &&
        role.role === Role.MiracleMerchant &&
        ctx.world.getComponent(actorId, COMPONENT.Camp)?.camp === Camp.Good &&
        role.privateState === privateState &&
        getMerchantState(role) === state &&
        livingNightLife(ctx.world, life);
      // 先完成原体／库存的原有序复验，再否决新交易；纯 ownerCurrent 仍供已付反噬使用。
      const current = () => ownerCurrent() && canMerchantTrade(state, day) && !isRoleExecutionRetired(role);
      if (!current()) continue;
      let completed = false;
      for (let attempt = 0; attempt < 3; attempt++) {
        if (!current()) break;
        const targets = new Map(
          ctx.world
            .getAliveEntityIds()
            .filter((id) => id !== actorId)
            .map((id) => {
              const targetRole = ctx.world.getComponent(id, COMPONENT.Role)!;
              return [
                id,
                {
                  life: captureNightLife(ctx.world, id)!,
                  role: targetRole,
                  kind: targetRole.role,
                  camp: ctx.world.getComponent(id, COMPONENT.Camp)?.camp,
                  privateState: targetRole.privateState,
                },
              ] as const;
            }),
        );
        // 候选捕获的原 getter 已全部执行；退休源不再打开新的请求，目标名单本身不按墓碑过滤。
        if (isRoleExecutionRetired(role)) break;
        let action: ToolCall | null = null;
        if (targets.size) {
          // 保原 receiver／getAction callee → makeRequest callee → 请求实参的求值序；不提前要求原 callee 可调用。
          const provider = ctx.actionProvider,
            getAction = provider.getAction,
            makeRequest = ctx.makeRequest,
            requestArgs = [actorId, ["bestow_ability"], {
              stage: "miracle_merchant",
              requiresAction: false,
              ...(attempt ? { retry_attempt: attempt, retry_max: 2 } : {}),
            }],
            invoke = Reflect.apply.bind(Reflect);
          // 新 Reflect／bind 查找与分配都先完成；末旗后只裸调用已准备 invoker，不再查方法属性。
          if (isRoleExecutionRetired(role)) break;
          const request = invoke(makeRequest, ctx, requestArgs), actionArgs = [request];
          // builder 已完成的请求前缀不回滚；它退休源时不再调用 provider，await 后仍走原 current。
          if (isRoleExecutionRetired(role)) break;
          action = await invoke(getAction, provider, actionArgs);
        }
        if (!current()) break;
        if (action === null) {
          // 空回复也会写当日关窗；只在首写之前拒绝，既有 callee 和局部实参顺序不改。
          const closeTrade = closeMerchantTrade;
          if (isRoleExecutionRetired(role)) break;
          closeTrade(state, day);
          recordCommit(ctx.world, day);
          ctx.events.push({
            timestamp: Date.now(),
            type: "merchant_trade_skipped",
            payload: { actorId, day },
          });
          completed = true;
          break;
        }
        if (action.name !== "bestow_ability") continue;
        const valid = ctx.toolGateway.validateAndSanitize(ctx.world, actorId, action, {
          phase: Phase.Night,
          day,
        });
        if (!current() || !valid.ok || valid.sanitizedCall?.name !== "bestow_ability") continue;
        const { target_id: targetId, skill } = valid.sanitizedCall.args,
          target = targets.get(targetId);
        if (
          !target ||
          !livingNightLife(ctx.world, target.life) ||
          ctx.world.getComponent(targetId, COMPONENT.Role) !== target.role ||
          target.role.role !== target.kind ||
          ctx.world.getComponent(targetId, COMPONENT.Camp)?.camp !== target.camp ||
          target.role.privateState !== target.privateState
        )
          continue;
        const failure = target.camp === Camp.Wolf;
        // 原 args／目标末字段与阵营判断已完成；Wolf 在 record 内首付，Good 由原赠予 owner 首装。
        if (isRoleExecutionRetired(role)) break;
        if (!failure) {
          const base = {
            id: "gift:miracle",
            activation: "lucky" as const,
            source: { kind: "gift" as const, actorId },
            sourceDisclosed: false,
            startsOnDay: day,
            maxUses: 1,
          };
          if (skill === "check")
            grantNightAbility(
              ctx.world,
              targetId,
              {
                ...base,
                kind: "seer_check",
                state: { lastTarget: null, lastIsWerewolf: null, lastResult: null, history: [] },
              },
              ctx.events,
            );
          if (skill === "guard")
            grantNightAbility(
              ctx.world,
              targetId,
              { ...base, kind: "guard", state: { lastTarget: null } },
              ctx.events,
            );
          if (skill === "poison")
            grantNightAbility(
              ctx.world,
              targetId,
              {
                ...base,
                kind: "potion",
                state: {
                  heal: 0,
                  poison: 1,
                  selfHealRule: WitchSelfHealRule.Disabled,
                  canSelfHeal: false,
                  healUsedThisNight: false,
                  poisonUsedThisNight: false,
                },
              },
              ctx.events,
            );
        }
        // Good 授予正常返回后属于已接受前缀；不以晚退休截断商人库存、记录和事实，原抛错仍传播。
        const recordTrade = recordMerchantTrade;
        if (failure && isRoleExecutionRetired(role)) break;
        recordTrade(state, day, targetId, skill as MiracleSkill);
        recordCommit(ctx.world, day);
        if (failure)
          (ctx.state.merchantBacklashes ??= []).push({ target: life, isCurrent: ownerCurrent });
        ctx.events.push({
          timestamp: Date.now(),
          type: "merchant_trade_committed",
          payload: { actorId, day, targetId, skill },
        });
        ctx.events.push({
          timestamp: Date.now(),
          type: "merchant_trade_resolved",
          payload: { actorId, day, targetId, skill, outcome: failure ? "backlash" : "granted" },
        });
        completed = true;
        break;
      }
      if (!completed && current()) throw new Error("merchant_valid_action_missing");
    }
  },
};

/**
 * 负责黑市商人在后置受赠行动之前选择交易。输入为原库存与已验证的技能／收货，输出为独立 gift／gun、反噬和事实。
 * 阵营保原捕获／复验点的实际 Camp 值，新请求和未付关窗／首付款之前拒绝退休源，不改变纯目标与知识名单。
 * ownerCurrent（含 paid 首死分支）保已付反噬的原身份／生命政策；Good 资源授予正常返回或 Wolf 首库存写后，
 * 其余库存、选择、记录和事实仍按原前缀完成，原异常传播且不退款，不给替换商人接续已付效果。
 */
import { closeBlackMarketTrade, recordBlackMarketTrade } from "./state";

import { COMPONENT } from "../../../../core/domain/components/names";
import { isRoleExecutionRetired } from "../../../../core/domain/role-execution-authority";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { Camp, Role, Phase, WitchSelfHealRule, type ToolCall } from "../../../../core/domain/model";
import { aliveLifeVersion } from "../../../../core/domain/components/alive";
import { captureNightLife, livingNightLife } from "../../../../core/domain/night_effects";
import type { World } from "../../../../core/domain/world";
import type { NightStageHandler } from "../../stages/night/contracts";
import { grantNightAbility } from "../night-ability-grants";
import { grantDeathGun } from "../death_abilities";
import { recipientAbilityStage } from "../recipient_ability_stage";
import { canBlackMarketTrade, getBlackMarketState } from "./state";
const committed = new WeakMap<World, Set<number>>();
export function hasBlackMarketNightCommit(world: World, day: number): boolean {
  return committed.get(world)?.has(day) ?? false;
}
function recordCommit(world: World, day: number): void {
  const days = committed.get(world) ?? new Set<number>();
  days.add(day);
  committed.set(world, days);
}
export const BLACK_MARKET_RECIPIENT_STAGE = recipientAbilityStage("black_market", 140);
export const BLACK_MARKET_TRADE_STAGE: NightStageHandler = {
  id: "black_market_merchant",
  priority: 130,
  async execute(ctx) {
    const day = ctx.currentDay();
    for (const actorId of ctx.getAliveByRole(Role.BlackMarketMerchant)) {
      const role = ctx.world.getComponent(actorId, COMPONENT.Role)!,
        state = getBlackMarketState(role),
        life = captureNightLife(ctx.world, actorId);
      if (!state || !life || ctx.world.getComponent(actorId, COMPONENT.Camp)?.camp !== Camp.Good) continue;
      const privateState = role.privateState;
      const ownerCurrent = (paid = false) =>
        ctx.isCurrent() &&
        ctx.currentDay() === day &&
        ctx.world.getComponent(actorId, COMPONENT.Role) === role &&
        role.role === Role.BlackMarketMerchant &&
        ctx.world.getComponent(actorId, COMPONENT.Camp)?.camp === Camp.Good &&
        role.privateState === privateState &&
        getBlackMarketState(role) === state &&
        (livingNightLife(ctx.world, life) ||
          (paid &&
            ctx.world.getComponent(actorId, COMPONENT.Alive) === life.life &&
            !life.life.alive &&
            aliveLifeVersion(life.life) === life.version + 1));
      // 先完成原体／库存的原有序复验，再否决新交易；纯 ownerCurrent 仍供已付反噬使用。
      const current = () => ownerCurrent() && canBlackMarketTrade(state, day) && !isRoleExecutionRetired(role);
      if (!current()) continue;
      const skip = () => {
        // null 或原无目标收尾都只是未付关窗；最后一次候选查询能退休源，故在关闭首写前单独拒绝。
        const closeTrade = closeBlackMarketTrade;
        if (isRoleExecutionRetired(role)) return;
        closeTrade(state, day);
        recordCommit(ctx.world, day);
        ctx.events.push({
          timestamp: Date.now(),
          type: "black_market_trade_skipped",
          payload: { actorId, day },
        });
      };
      let completed = false;
      for (let attempt = 0; attempt < 3; attempt++) {
        if (!current()) break;
        const targets = new Map(
          ctx.world
            .getAliveEntityIds()
            .filter((id) => id !== actorId)
            .map((id) => {
              const targetRole = ctx.world.getComponent(id, COMPONENT.Role)!;
              return [
                id,
                {
                  life: captureNightLife(ctx.world, id)!,
                  role: targetRole,
                  kind: targetRole.role,
                  camp: ctx.world.getComponent(id, COMPONENT.Camp)?.camp,
                  privateState: targetRole.privateState,
                },
              ] as const;
            }),
        );
        // 候选捕获的原 getter 已全部执行；退休源不再打开新的请求，目标名单本身不按墓碑过滤。
        if (isRoleExecutionRetired(role)) break;
        let action: ToolCall | null = null;
        if (targets.size) {
          // 保原 receiver／getAction callee → makeRequest callee → 请求实参的求值序；不提前要求原 callee 可调用。
          const provider = ctx.actionProvider,
            getAction = provider.getAction,
            makeRequest = ctx.makeRequest,
            requestArgs = [actorId, ["black_market_trade"], {
              stage: "black_market_merchant",
              requiresAction: false,
              action_failure_policy: "error",
              allow_fallback: false,
              ...(attempt ? { retry_attempt: attempt, retry_max: 2 } : {}),
            }],
            invoke = Reflect.apply.bind(Reflect);
          // 新 Reflect／bind 查找与分配都先完成；末旗后只裸调用已准备 invoker，不再查方法属性。
          if (isRoleExecutionRetired(role)) break;
          const request = invoke(makeRequest, ctx, requestArgs), actionArgs = [request];
          // builder 已完成的请求前缀不回滚；它退休源时不再调用 provider，await 后仍走原 current。
          if (isRoleExecutionRetired(role)) break;
          action = await invoke(getAction, provider, actionArgs);
        }
        if (!current()) break;
        if (action === null) {
          skip();
          completed = true;
          break;
        }
        if (action.name !== "black_market_trade") continue;
        const validated = ctx.toolGateway.validateAndSanitize(ctx.world, actorId, action, {
          phase: Phase.Night,
          day,
        });
        if (!current() || !validated.ok || validated.sanitizedCall?.name !== "black_market_trade")
          continue;
        const { target_id: targetId, skill } = validated.sanitizedCall.args,
          target = targets.get(targetId);
        if (
          !target ||
          !livingNightLife(ctx.world, target.life) ||
          ctx.world.getComponent(targetId, COMPONENT.Role) !== target.role ||
          target.role.role !== target.kind ||
          ctx.world.getComponent(targetId, COMPONENT.Camp)?.camp !== target.camp ||
          target.role.privateState !== target.privateState
        )
          continue;
        if (target.camp !== Camp.Good && target.camp !== Camp.Wolf)
          throw new Error("black_market_target_camp_unsupported");
        const failed = target.camp === Camp.Wolf;
        // 原目标 getter／unsupported-Camp 错误仍先发生；只在 Wolf 首付或 Good 资源授予之前拒绝退休源。
        if (isRoleExecutionRetired(role)) break;
        if (!failed) {
          if (skill === "gun") grantDeathGun(ctx.world, actorId, targetId, day, ctx.events);
          else {
            const base = {
              id: "gift:black-market",
              activation: "black_market" as const,
              source: { kind: "gift" as const, actorId },
              sourceDisclosed: false,
              startsOnDay: day + 1,
              maxUses: 1,
            };
            if (skill === "check")
              grantNightAbility(
                ctx.world,
                targetId,
                {
                  ...base,
                  kind: "seer_check",
                  state: { lastTarget: null, lastIsWerewolf: null, lastResult: null, history: [] },
                },
                ctx.events,
              );
            else
              grantNightAbility(
                ctx.world,
                targetId,
                {
                  ...base,
                  kind: "potion",
                  state: {
                    heal: 0,
                    poison: 1,
                    selfHealRule: WitchSelfHealRule.Disabled,
                    canSelfHeal: false,
                    healUsedThisNight: false,
                    poisonUsedThisNight: false,
                  },
                },
                ctx.events,
              );
          }
        }
        // Good gift／gun 正常返回后不再加墓碑；晚退休不能取消商人库存与已付反噬／通知完成前缀。
        const recordTrade = recordBlackMarketTrade;
        if (failed && isRoleExecutionRetired(role)) break;
        recordTrade(state, day, targetId, skill);
        recordCommit(ctx.world, day);
        const choice = state.choice!;
        if (failed)
          (ctx.state.blackMarketBacklashes ??= []).push({
            target: life,
            isCurrent: () =>
              ownerCurrent(true) &&
              state.choice === choice &&
              choice.day === day &&
              choice.targetId === targetId &&
              choice.skill === skill,
          });
        ctx.events.push({
          timestamp: Date.now(),
          type: "black_market_trade_committed",
          payload: { actorId, day, targetId, skill },
        });
        ctx.events.push({
          timestamp: Date.now(),
          type: "black_market_trade_resolved",
          payload: { actorId, day, targetId, skill, outcome: failed ? "backlash" : "granted" },
        });
        completed = true;
        break;
      }
      if (!completed && current()) {
        if (ctx.world.getAliveEntityIds().some((id) => id !== actorId))
          throw new Error("black_market_valid_action_missing");
        skip();
      }
    }
  },
};

/**
 * 单元验证两类商人的未付执行退休边界，输入为真实合法六人板、可等待 provider 和明确 getter／sink 故障。
 * 独立字面库存、关窗、提案、资源与同 Error 断言区分首写之前拒绝和已付前缀继续，不复制生产资格谓词。
 * 每例只执行本商人阶段与公开 gateway／资源查询，不运行完整夜、模型或历史 F04／F05 已绿用例。
 */
import { expect, test } from "bun:test";
import { bootstrapGame } from "../../../src/app/bootstrap";
import {
  Camp, COMPONENT, Phase, Role, WinCondition,
  type GameEvent, type ToolCall,
} from "../../../src/core";
import { retireRoleExecution, isRoleExecutionRetired } from "../../../src/core/domain/role-execution-authority";
import { sixPlayerMvpConfig } from "../../../src/runtime/scenarios/six_player_mvp";
import { GameActionRequestFactory } from "../../../src/game/engine/action_request_factory";
import { nightStageContext } from "../../support/builders/night-stage-context";
import type { NightStageContext } from "../../../src/game/mechanisms/stages/night/contracts";
import { MIRACLE_MERCHANT_STAGE, hasMerchantNightCommit } from "../../../src/game/mechanisms/roles/miracle_merchant/night_stage";
import { BLACK_MARKET_TRADE_STAGE, hasBlackMarketNightCommit } from "../../../src/game/mechanisms/roles/black_market_merchant/night_stage";
import { getMerchantState } from "../../../src/game/mechanisms/roles/miracle_merchant/state";
import { getBlackMarketState } from "../../../src/game/mechanisms/roles/black_market_merchant/state";
import { allNightAbilities } from "../../../src/game/mechanisms/roles/abilities";
import { allDeathGuns } from "../../../src/game/mechanisms/roles/death_abilities";

type Family = "miracle" | "black";
const kind = (family: Family) => family === "miracle" ? Role.MiracleMerchant : Role.BlackMarketMerchant;
const stage = (family: Family) => family === "miracle" ? MIRACLE_MERCHANT_STAGE : BLACK_MARKET_TRADE_STAGE;
function choose(family: Family, target: number, gun = false): ToolCall {
  return family === "miracle"
    ? { name: "bestow_ability", args: { target_id: target, skill: "check" } }
    : { name: "black_market_trade", args: { target_id: target, skill: gun ? "gun" : "check" } };
}

/** 两族各用其实际支持的合法六人板；原 Camp／库存由 bootstrap 创建，不挂 Role.camp 或测试镜像。 */
function fixture(family: Family) {
  const roles = [kind(family), Role.Wolf, Role.Wolf, Role.Seer, Role.Witch, Role.Villager];
  const game = bootstrapGame({
    ...sixPlayerMvpConfig,
    roleSetups: [...new Set(roles)].map(role => ({ role, count: roles.filter(r => r === role).length })),
    winConditions: [WinCondition.SlaughterCity],
    selfDestruct: { enabledWindows: [] },
  }, { fixedRoles: roles });
  const events: GameEvent[] = [], actor = game.world.getComponent(1, COMPONENT.Role)!;
  const stock = family === "miracle" ? getMerchantState(actor)! : getBlackMarketState(actor)!;
  const factory = new GameActionRequestFactory(game.world, events, 1);
  const ctx = nightStageContext({
    world: game.world,
    events,
    actionProvider: { getAction: async () => choose(family, 2) },
    getAliveByRole: role => game.world.getAliveEntityIds().filter(id => game.world.getComponent(id, COMPONENT.Role)?.role === role),
    makeRequest: (actorId, allowedTools, extra) => factory.create({
      actorId, allowedTools, phase: Phase.Night, stage: extra.stage,
      requiresAction: extra.requiresAction ?? true,
      summary: { key: "request.summary.night_action" }, context: extra,
    }),
    state: { wolfChatOrder: [], endedWolves: new Set(), wolfVotes: {}, wolfTarget: null, seerChecks: [], merchantBacklashes: [], blackMarketBacklashes: [] },
  });
  return { game, events, actor, stock, ctx };
}
const committed = (family: Family, f: ReturnType<typeof fixture>) =>
  family === "miracle" ? hasMerchantNightCommit(f.game.world, 1) : hasBlackMarketNightCommit(f.game.world, 1);

for (const family of ["miracle", "black"] as const) {
  test(`${family}: retired original opens no request; fresh actor may trade with a retired pure Wolf target`, async () => {
    const f = fixture(family);
    let providers = 0;
    f.ctx.actionProvider.getAction = async () => { providers++; return choose(family, 2); };
    retireRoleExecution(f.actor);
    const result = f.ctx.toolGateway.validateAndSanitize(f.game.world, 1, choose(family, 2), { phase: Phase.Night, day: 1 });
    expect(result.ok).toBe(false);
    expect(result.error).toBe("merchant_unavailable");
    await stage(family).execute(f.ctx);
    expect(providers).toBe(0);
    expect(f.stock).toEqual({ remaining: 1, closedDay: null, choice: null });
    expect(f.events).toEqual([]);
    expect(committed(family, f)).toBe(false);

    // 换对象并不清除旧对象墓碑；新对象仍走全部真实规则，退休目标不变成全局数据过滤。
    const fresh = { ...f.actor };
    f.game.world.addComponent(1, COMPONENT.Role, fresh);
    retireRoleExecution(f.game.world.getComponent(2, COMPONENT.Role)!);
    await stage(family).execute(f.ctx);
    expect(isRoleExecutionRetired(f.actor)).toBe(true);
    expect(isRoleExecutionRetired(fresh)).toBe(false);
    expect(providers).toBe(1);
    expect(f.stock).toEqual({ remaining: 0, closedDay: 1, choice: { day: 1, targetId: 2, skill: "check" } });
    expect(f.game.world.getComponent(1, COMPONENT.Camp)!.camp).toBe(Camp.Good);
    expect(committed(family, f)).toBe(true);
  });

  test(`${family}: true suspended null response and no-target capture cannot close a retired unpaid day`, async () => {
    const f = fixture(family);
    let finish!: (call: ToolCall | null) => void, providers = 0;
    f.ctx.actionProvider.getAction = () => { providers++; return new Promise<ToolCall | null>(resolve => { finish = resolve; }); };
    const pending = stage(family).execute(f.ctx);
    expect(providers).toBe(1);
    retireRoleExecution(f.actor);
    finish(null);
    await pending;
    expect(f.stock).toEqual({ remaining: 1, closedDay: null, choice: null });
