    expect(f.events.map(row => row.type)).toEqual(family === "miracle"
      ? ["ability_changed", "merchant_trade_committed", "merchant_trade_resolved"]
      : ["death_ability_changed", "black_market_trade_committed", "black_market_trade_resolved"]);
    const target = f.game.world.getComponent(6, COMPONENT.Role)!;
    if (family === "miracle") expect(allNightAbilities(target)).toMatchObject([{ id: "gift:miracle", uses: 0, maxUses: 1 }]);
    else expect(allDeathGuns(target)).toMatchObject([{ kind: "gun", remaining: 1, armedOnNight: null }]);
